export const Schema = z.object({
    机体状态: z
        .object({
        电量: z.coerce.number().transform(value => _.clamp(value, 0, 100)).prefault(100),
        冷却液: z.coerce.number().transform(value => _.max([value, 0])).prefault(3),
        体液: z.coerce.number().transform(value => _.max([value, 0])).prefault(3),
        润滑油: z.coerce.number().transform(value => _.max([value, 0])).prefault(3),
        // 机体内容量（独立于耗材库存「几罐」：机体内液量百分比，0-100）
        冷却液容量: z.coerce.number().transform(value => _.clamp(value, 0, 100)).prefault(70),
        体液容量: z.coerce.number().transform(value => _.clamp(value, 0, 100)).prefault(75),
        润滑油容量: z.coerce.number().transform(value => _.clamp(value, 0, 100)).prefault(85),
    })
        .prefault({}),
    结构: z
        .record(z.enum(['头部', '胸段', '腹段', '左上臂', '左前臂', '左手', '右上臂', '右前臂', '右手', '左大腿', '左小腿', '左脚', '右大腿', '右小腿', '右脚']), z.enum(['完好', '受损', '损毁', '拆除']))
        .prefault({
        头部: '完好',
        胸段: '完好',
        腹段: '完好',
        左上臂: '完好',
        左前臂: '完好',
        左手: '完好',
        右上臂: '完好',
        右前臂: '完好',
        右手: '完好',
        左大腿: '完好',
        左小腿: '完好',
        左脚: '完好',
        右大腿: '完好',
        右小腿: '完好',
        右脚: '完好',
    }),
    模块: z
        .record(z.enum(['处理器', '逻辑模块', '人格模块', '记忆模块', '视觉模块', '听觉模块', '语言模块', '表情模块', '辅助控制操作主板', '电子脑', '电子脑主系统主板', '散热系统', '体液系统', '电力系统', '生殖模块', '传动系统', '机械骨骼', '传感系统', '皮肤外壳']), z
        .object({
        当前耐久: z.coerce.number().transform(value => _.clamp(value, 0, 100)).prefault(100),
        最大耐久: z.coerce.number().prefault(100),
        // 子目录：同模块多位置部件独立耐久（总目录耐久 = 子项均值四舍五入取整）
        子项: z
            .record(z.string().describe('子项名'), z
            .object({
            当前耐久: z.coerce.number().transform(value => _.clamp(value, 0, 100)).prefault(100),
            最大耐久: z.coerce.number().prefault(100),
            // —— 当前装配部件（叙事层，供 AI 读；数字属性如价格/效果留在前端目录，不在此处）——
            // 客观描述：是什么 / 外观 / 材质 / 功能，不带主观评价与数字属性。
            型号: z.string().optional().describe('当前装配部件型号，如：原厂液循环组 LC-89001'),
            介绍: z.string().optional().describe('当前装配部件介绍（客观，供 AI 叙事）'),
            写作指导: z.string().optional().describe('当前装配部件写作指导（客观，供 AI 叙事：动作/受损时的表现）'),
        })
            .prefault({}))
            .prefault({}),
    })
        .prefault({}))
        .prefault({
        处理器: { 当前耐久: 100, 最大耐久: 100 },
        逻辑模块: { 当前耐久: 100, 最大耐久: 100 },
        人格模块: { 当前耐久: 100, 最大耐久: 100 },
        记忆模块: { 当前耐久: 100, 最大耐久: 100 },
        视觉模块: { 当前耐久: 100, 最大耐久: 100 },
        听觉模块: { 当前耐久: 100, 最大耐久: 100 },
        语言模块: { 当前耐久: 100, 最大耐久: 100 },
        表情模块: { 当前耐久: 100, 最大耐久: 100 },
        辅助控制操作主板: { 当前耐久: 100, 最大耐久: 100 },
        电子脑: { 当前耐久: 100, 最大耐久: 100 },
        散热系统: { 当前耐久: 100, 最大耐久: 100 },
        体液系统: { 当前耐久: 100, 最大耐久: 100 },
        电力系统: { 当前耐久: 100, 最大耐久: 100 },
        生殖模块: { 当前耐久: 100, 最大耐久: 100 },
        传动系统: { 当前耐久: 100, 最大耐久: 100 },
        机械骨骼: { 当前耐久: 100, 最大耐久: 100 },
        传感系统: { 当前耐久: 100, 最大耐久: 100 },
        皮肤外壳: { 当前耐久: 100, 最大耐久: 100 },
    }),
    经营: z
        .object({
        信用点: z.coerce.number().prefault(5000),
        粉丝: z.coerce.number().transform(value => _.max([value, 0])).prefault(0),
        名声: z.coerce.number().transform(value => _.max([value, 0])).prefault(0),
        天数: z.coerce.number().transform(value => _.max([value, 1])).prefault(1),
        难度: z.enum(['轻松', '标准', '困难', '自由故事']).prefault('标准'),
        住所: z
            .object({
            档次: z.string().prefault('出租屋'),
            每期开销: z.coerce.number().prefault(2200),
            距缴费天数: z.coerce.number().prefault(14),
        })
            .prefault({}),
        // 订阅型服务（网络流量/云备份/机体险）：服务类商品购买后进入此表，按期自动续费，周期 14 天（与住所一致）。
        订阅: z
            .record(z.string().describe('订阅项名'), z
            .object({
            每期开销: z.coerce.number().prefault(0),
            距缴费天数: z.coerce.number().prefault(14),
        })
            .prefault({}))
            .prefault({}),
    })
        .prefault({}),
    拍摄: z
        .object({
        进行中: z.boolean().prefault(false),
        档位: z.string().prefault(''),
    })
        .prefault({}),
    结算: z
        .record(z.string().describe('视频名'), z
        .object({
        类型: z.string().describe('视频类型（常规/擦边/NSFW/机损/自毁/科普/日常…）').prefault(''),
        剩余天数: z.coerce.number().prefault(0),
        每日金钱: z.coerce.number().prefault(0),
        每日粉丝: z.coerce.number().prefault(0),
        每日名声: z.coerce.number().prefault(0),
    })
        .prefault({}))
        .prefault({}),
    物品: z
        .record(z.string().describe('物品名（类型七类：耗材/部件/服装/设备/服务/其他/房产；房产为住所，档次制，不进库存）'), z
        .object({
        // —— 物品「定义」（类型/价格/效果/部位/可否自换/更换耗电/穿着位置/型号/描述）——
        // 单一数据源在前端物品目录（itemRegistry.ts，数字属性，供前端展示/结算/筛选）。
        // AI 不读数字属性；AI 通过变量只读「持有状态」（数量/送达天数/配送数量），
        // 以及「当前装备/当前穿着」的叙事字段（见 模块.子项 与 当前穿着）。
        // 此处定义字段为兼容旧档保留（prefault），新档由前端物品目录提供，前端只读。
        类型: z.string().prefault(''),
        数量: z.coerce.number().prefault(0),
        价格: z.coerce.number().prefault(0),
        效果: z.string().prefault(''),
        送达天数: z.coerce.number().prefault(0),
        配送数量: z.coerce.number().optional().describe('配送中（在途）件数，用于物流条展示'),
        // —— 创意工坊物品库接口字段（脚本 / 世界书可写，前端只读展示）——
        部位: z.string().optional().describe('部件可安装部位（如：体液系统 / 散热系统 / 左大腿）'),
        可否自换: z.boolean().optional().describe('能否在家中自行更换；false = 需维修店'),
        更换耗电: z.coerce.number().optional().describe('家中更换消耗的机体电量（0-100）'),
        更换耗时: z.coerce.number().optional().describe('家中自行更换耗时（小时，AI 推进叙事时间依据）'),
        穿着位置: z.union([z.string(), z.array(z.string())]).optional().describe('服装占用的穿着位置：单件 string（如「上身」），多槽 string[]（如「上身」「下装」）；取值：头部/内衣/上身/下装/外套/袜子/足部/涂层'),
        型号: z.string().optional().describe('部件型号，如：原厂液循环组 LC-89001'),
        厂家: z.string().optional().describe('生产厂家'),
        描述: z.string().optional().describe('物品描述'),
    })
        .prefault({}))
        .prefault({
        // 默认开局：持有两套服装（居家服 + 出厂内衣），机体初始全裸（当前穿着留空）。
        // 后续「自定义开局系统」会覆盖这里的默认值。
        居家上衣: { 数量: 1 },
        居家短裤: { 数量: 1 },
        出厂内衣: { 数量: 1 },
    }),
    // 当前穿着：按穿着位置记录现在穿什么（叙事层，供 AI 读；数字属性留前端目录）。
    // 客观描述：名称 + 介绍 + 写作指导，不带主观评价与价格/效果数字。
    当前穿着: z
        .record(z.enum(['头部', '内衣', '上身', '下装', '外套', '袜子', '足部', '涂层']), z
        .object({
        名称: z.string().prefault(''),
        介绍: z.string().optional().describe('该穿着位置的介绍（客观，供 AI 叙事）'),
        写作指导: z.string().optional().describe('该穿着的写作指导（客观，供 AI 叙事）'),
    })
        .prefault({}))
        .prefault({}),
    改造件: z
        .record(z.string().describe('改造件名'), z
        .object({
        部位: z.string().prefault(''),
        效果: z.string().prefault(''),
        // 并入分类：改造件默认按「部件」展示（物品页七分类：耗材/部件/服装/设备/服务/其他/房产）
        类型: z.string().optional().describe('并入分类（部件等）'),
    })
        .prefault({}))
        .prefault({}),
}).prefault({});
